<script setup lang="ts">
// a choice put to the whole table
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { app, gs, act, say, peek } from '../session'
import { ABILITIES, ABILITY_NAME, SKILLS, SKILL_NAME, signed, type Ability, type Skill } from '../rules/base'
import { rich } from './rich'
import type { Scene } from '../dm/module'
import { stageScene } from '../session'
const S = computed(() => (gs.value as any)?.scene as Scene | null); const text = ref(''), fold = ref(false); const dm = computed(() => app.role === 'dm' && !app.seat); const up = computed(() => { const h = gs.value?.chars[app.seat]; return !!h && h.hp > 0 && !h.dead })
const skill = (s?: string) => !s ? '' : s in SKILLS ? SKILL_NAME[s as Skill] : ABILITIES.includes(s as Ability) ? ABILITY_NAME[s as Ability] : s; const mine = (s?: string) => { const R = peek(); if (!s || !R || !app.seat) return ''; return signed(R.checkMod(app.seat, s in SKILLS ? s as Skill : undefined, (s in SKILLS ? SKILLS[s as Skill] : s) as Ability)) }
const pick = (i: number) => { if (!up.value) return; void act({ k: 'pick', i }, app.seat) }; const votes = (i: number) => Object.entries(S.value?.votes ?? {}).filter(([, v]) => v === i).map(([id]) => gs.value?.chars[id]?.name.split(' ')[0]).filter(Boolean); const many = computed(() => app.players.filter(p => p.online).length > 0); const opts = computed(() => (S.value?.opts ?? []).filter(o => o.off !== 'hidden')); const guess = () => { const t = text.value.trim(); if (t) { say(t, 'say'); text.value = '' } }; const KIND: Record<string, string> = { scene: '', trial: 'Together', puzzle: 'A riddle', fight: '', boss: '', travel: 'A journey' }
const key = (e: KeyboardEvent) => { const d = /^(?:Digit|Numpad)([1-9])$/.exec(e.code); if (!d || !S.value || fold.value || app.modal || (gs.value?.calls ?? []).some(c => c.who === app.seat) || ['INPUT', 'TEXTAREA', 'SELECT'].includes((e.target as HTMLElement)?.tagName) || e.ctrlKey || e.altKey || e.metaKey) return; const o = opts.value[+d[1] - 1]; if (!o || dm.value) return; e.preventDefault(); e.stopImmediatePropagation(); if (!o.off && !S.value.used.includes(o.i) && !S.value.wait) pick(o.i) }; onMounted(() => addEventListener('keydown', key, true)); onBeforeUnmount(() => removeEventListener('keydown', key, true))
</script>
<template><section v-if="S" class="sc paper" :class="[S.kind, { fold }]"><header @click="fold = !fold"><h3>{{ S.name }}</h3><small v-if="S.kind === 'trial' && S.prog">{{ S.prog.ok }} of {{ S.prog.need }} done, {{ S.prog.bad }} of {{ S.prog.limit }} lost</small><small v-else-if="many && Object.keys(S.votes).length">The table is choosing</small><small v-else>{{ KIND[S.kind] }}</small><button class="fo" :aria-label="fold ? 'Open' : 'Fold'">{{ fold ? '＋' : '－' }}</button></header>
  <template v-if="!fold"><p v-if="S.kind === 'travel' && S.text" class="aloud" v-html="rich(S.text)" /><div v-if="S.prog" class="pips"><i v-for="n in S.prog.need" :key="'a' + n" :class="{ on: n <= S.prog.ok }" /><u v-for="n in S.prog.limit" :key="'b' + n" :class="{ on: n <= S.prog.bad }" /></div>
    <ol><li v-for="(o, n) in opts" :key="o.i"><button :disabled="!!o.off || S.used.includes(o.i) || !!S.wait || !up" :class="{ used: S.used.includes(o.i), on: S.votes[app.seat] === o.i }" @click="pick(o.i)"><b>{{ n + 1 }}</b><span><i v-html="rich(o.t)" /><small v-if="o.off">{{ o.off }}</small></span><em v-if="o.cost">{{ o.cost }} gold</em><em v-if="o.skill">{{ skill(o.skill) }}<i>{{ mine(o.skill) }}</i></em><q v-if="votes(o.i).length">{{ votes(o.i).join(', ') }}</q></button></li></ol>
    <form v-if="S.ask" class="as" @submit.prevent="guess"><input v-model="text" class="field" placeholder="Say the answer" aria-label="Say the answer" maxlength="80"><button class="btn primary">Say it</button></form>
    <footer v-if="S.wait || dm || (up && S.kind !== 'travel')"><span v-if="S.wait">{{ gs?.chars[S.wait]?.name }} is trying.</span><button v-else-if="up && S.kind !== 'travel'" class="btn quiet sm" @click="pick(-9)">Leave it for now<template v-if="votes(-9).length"> ({{ votes(-9).join(', ') }})</template></button><button v-if="dm" class="btn sm" @click="stageScene('close')">Close the scene</button></footer></template></section></template>
<style scoped>
.sc{width:min(620px,94vw);border-top:8px solid var(--spot);max-height:min(54vh,560px);display:flex;flex-direction:column;pointer-events:auto;animation:rise .16s}.sc>ol{overflow:auto}header{display:flex;align-items:baseline;gap:14px;padding:11px 18px 9px;cursor:pointer}h3{font-size:27px}header small{color:var(--ink2);font-size:15px}.fo{margin-left:auto;font:600 22px/1 var(--ui);width:28px;text-align:center}.aloud{padding:0 18px;font-size:18.5px;margin:0 0 8px}.pips{display:flex;gap:5px;padding:0 18px 9px}.pips i,.pips u{width:26px;height:14px;border:2px solid var(--ink)}.pips i.on{background:var(--good)}.pips u.on{background:var(--bad)}.pips u:first-of-type{margin-left:16px}
ol{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}li{border-bottom:1px solid var(--line)}li button{display:flex;align-items:center;gap:12px;width:100%;padding:9px 18px;min-height:46px;flex-wrap:wrap}li b{font:800 23px/1 var(--serif);width:20px;flex:none}li span{flex:1;min-width:50%;font-size:17.5px;line-height:1.22}li span>i{font-style:normal}li span small{display:block;font-size:14.5px;color:var(--bad)}li em{font-style:normal;font-size:15.5px;white-space:nowrap}li em i{font:700 19px/1 var(--serif);font-style:normal;margin-left:8px}li q{quotes:none;background:var(--ink);color:var(--paper);font-size:14px;padding:1px 8px}li button:hover:not(:disabled),li button.on{background:var(--spot);color:var(--on-spot)}li button:disabled{opacity:.5}li .used span{text-decoration:line-through}.as{display:flex;gap:10px;padding:10px 18px}.as .field{font-size:18px}footer{display:flex;gap:8px;align-items:center;padding:6px 12px;min-height:38px;font-size:15.5px}footer span{padding-left:6px}
</style>
